window.AUTH=window.AUTH||{};window.AUTH["25-735"]={"d":"25-735","id":"2026/25-735","n":"Johnson v. United States Congress","briefs":[{"k":"petitioner","label":"Brief of petitioner Floyd Johnson","date":"2026-06-01","url":"https://www.supremecourt.gov/DocketPDF/25/25-735/412251/20260601114507068_25-735_ts.pdf","side":"pet","n":60},{"k":"respondent","label":"Brief of respondent United States Congress","date":"2026-07-13","url":"https://www.supremecourt.gov/DocketPDF/25/25-735/416400/20260713192231875_25-735_Johnson_bs_with%20appendix.pdf","side":"res","n":92},{"k":"reply","label":"Reply of petitioner Floyd Johnson","date":"2026-08-12","url":"https://www.supremecourt.gov/DocketPDF/25/25-735/418796/20260812130337373_25-735_tsrb.pdf","side":"pet","n":25}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"581 U.S. 468","y":2017,"id":"2016/16-74","sc":1,"by":{"0":"22"}},{"t":"case","label":"Am. Hosp. Ass’n v. Becerra","cite":"596 U.S. 724","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/724/","sc":1,"by":{"0":"39"}},{"t":"case","label":"Axon Enter., Inc. v. FTC","cite":"598 U.S. 175","y":2023,"id":"2022/21-86","sc":1,"by":{"0":"15-16, 31, 39-41, 43-44","1":"15-17, 39, 41, 42","2":"21-22"},"q":[{"src":"brief","b":0,"text":"providing in so many words that district court jurisdiction will yield.","cite":"598 U.S. 175, 185"},{"src":"brief","b":0,"text":"impossible to remedy once the [administrative] proceeding is over.","cite":"598 U.S. at 191"},{"src":"brief","b":1,"text":"substitute for that district court authority an alternative scheme of review","cite":"598 U.S. 175, 185"},{"src":"brief","b":1,"text":"whether the particular claims brought were ‘of the type Congress intended to be reviewed within’","cite":"598 U.S. at 186"}]},{"t":"case","label":"Bufkin v. Collins","cite":"604 U.S. 369","y":2025,"url":"https://supreme.justia.com/cases/federal/us/604/369/","sc":1,"by":{"0":"8-9, 17","1":"21"},"q":[{"src":"brief","b":0,"text":"modeled after the scope-of-review provision in the Administrative Procedure Act.","cite":"604 U.S. at 374"},{"src":"brief","b":0,"text":"lacks jurisdiction to review most factual determinations.","cite":"604 U.S. at 375"}]},{"t":"case","label":"Califano v. Sanders","cite":"430 U.S. 99","y":1977,"id":"1976/75-1443","sc":1,"by":{"0":"24"},"q":[{"src":"brief","b":0,"text":"[c]onstitutional questions obviously are unsuited to resolution in administrative hearing procedures.","cite":"430 U.S. 99, 109"}]},{"t":"case","label":"Copeland v. Shinseki","cite":"26 Vet. App. 86","y":2012,"url":"https://www.courtlistener.com/c/Vet.%20App./26/86/","by":{"0":"25"}},{"t":"case","label":"Elgin v. Dep’t of Treasury","cite":"567 U.S. 1","y":2012,"id":"2011/11-45","sc":1,"by":{"0":"3, 11, 14, 16, 24, 37-44","1":"3, 11, 16, 23, 25, 27, 39-42","2":"16, 20"},"q":[{"src":"brief","b":0,"text":"claims that attack the validity of a statute based on its inherent characteristics, not as a result of how the statute has been applied.","cite":"567 U.S. 1, 35"},{"src":"brief","b":0,"text":"whether the oft-stated principle that agencies cannot declare a statute unconstitutional is truly a matter of jurisdiction.","cite":"567 U.S. at 17"},{"src":"brief","b":1,"text":"‘whether Congress’ intent to preclude district court jurisdiction is fairly discernible in the statutory scheme.’","cite":"567 U.S. 1, 9-10"},{"src":"brief","b":1,"text":"determine[s] the scope of preclusion simply by interpreting the words Congress has chosen.","cite":"567 U.S. 1, 25"},{"src":"argument","who":"Mr. Chen","text":"That is the formulation that you, Justice Alito, used in -- in the Elgin dissent. But it also is -- it is an attack on statutory validity rather than misused agency discretion."},{"src":"argument","who":"Mr. Barber","text":"This is why the Court said in Elgin that the distinction between facial and as-applied claims are very amorphous, hard to get your hands around."}]},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"by":{"0":"35"},"q":[{"src":"brief","b":0,"text":"legislative history is not the law.","cite":"584 U.S. 497, 523"}]},{"t":"case","label":"Free Enter. Fund v. PCAOB","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"by":{"0":"31, 39","1":"41"}},{"t":"case","label":"Frontiero v. Richardson","cite":"411 U.S. 677","y":1973,"id":"1972/71-1694","sc":1,"by":{"0":"30"}},{"t":"case","label":"Georgia v. Public.Resource.Org, Inc.","cite":"590 U.S. 255","y":2020,"id":"2019/18-1150","sc":1,"by":{"0":"18"},"q":[{"src":"brief","b":0,"text":"the construction given by this Court to such language.","cite":"590 U.S. 255, 270"}]},{"t":"case","label":"Giancaterino v. Brown","cite":"7 Vet. App. 555","y":1995,"url":"https://www.courtlistener.com/c/Vet.%20App./7/555/","by":{"0":"25"}},{"t":"case","label":"Helsinn Healthcare S.A. v. Teva Pharm. USA, Inc.","cite":"586 U.S. 123","y":2019,"id":"2018/17-1229","sc":1,"by":{"0":"19, 32","2":"5-6"},"q":[{"src":"brief","b":0,"text":"it adopted the earlier judicial construction.","cite":"586 U.S. 123, 131"},{"src":"brief","b":0,"text":"adopted also the construction given by this Court,","cite":"586 U.S. at 131"}]},{"t":"case","label":"Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"by":{"0":"8, 26, 28, 37","1":"4, 7, 37","2":"13"},"q":[{"src":"brief","b":1,"text":"The VA’s adjudicatory ‘process is designed to function throughout with a high degree of informality and solicitude for the claimant.’","cite":"562 U.S. 428, 431"}]},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"by":{"0":"40"},"q":[{"src":"brief","b":0,"text":"readily assure themselves of their power to hear a case.","cite":"559 U.S. 77, 94"}]},{"t":"case","label":"Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"id":"2017/15-1204","sc":1,"by":{"0":"39"}},{"t":"case","label":"Johnson v. Robison","cite":"415 U.S. 361","y":1974,"id":"1973/72-1297","sc":1,"by":{"0":"2, 4-5, 8, 11-20, 24, 29-30, 32-36, 43","1":"3, 5, 6, 13, 19, 25-30, 33, 34","2":"1, 3, 5-7, 10, 15-17, 19"},"q":[{"src":"brief","b":0,"text":"decision of law or fact ‘under’ a statute is made by the Administrator in the interpretation or application of a particular provision of the statute to a particular set of facts.","cite":"415 U.S. at 367"},{"src":"brief","b":0,"text":"interpretation or application of a particular provision of the statute to a particular set of facts.","cite":"415 U.S. at 367"},{"src":"brief","b":1,"text":"on any question of law or fact under any law * * * providing benefits for veterans * * * shall be final and conclusive and no other official or any court of the United States shall have power or jurisdiction to review any such decision.","cite":"415 U.S. at 364"},{"src":"brief","b":1,"text":"bar[] federal courts from deciding the constitutionality of veterans’ benefits legislation.","cite":"415 U.S. at 366"},{"src":"argument","who":"Mr. Chen","text":"That's how this Court construed the same phrase in Robison. And deciding a statute's validity is not necessary to a decision under the statute."},{"src":"argument","who":"Mr. Chen","text":"So our position, the line that we have always tried to drawn is -- draw is the line that this Court drew in Robison. On one side of that line is challenges to statutes, and on the other side of the line is challenges to agency action, constitutional and otherwise."},{"src":"argument","who":"Justice Jackson","text":"-- versus other kinds of claims. And I appreciate that Robison has that language in it."}]},{"t":"case","label":"King v. St. Vincent’s Hosp.","cite":"502 U.S. 215","y":1991,"id":"1991/90-889","sc":1,"by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"the canon that provisions for benefits to members of the Armed Services are to be construed in the beneficiaries’ favor.","cite":"502 U.S. 215, 22021 n.9"}]},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"568 U.S. 519","y":2013,"id":"2012/11-697","sc":1,"by":{"0":"18"}},{"t":"case","label":"Larrabee v. Derwinski","cite":"968 F.2d 1497","y":1992,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/968/1497/","by":{"0":"16"}},{"t":"case","label":"Martin v. O’Rourke","cite":"891 F.3d 1338","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/891/1338/","by":{"0":"30","2":"17"},"q":[{"src":"brief","b":0,"text":"many veterans find themselves trapped for years.","cite":"891 F.3d 1338, 1349"}]},{"t":"case","label":"Mathews v. Diaz","cite":"426 U.S. 67","y":1976,"id":"1974/73-1046","sc":1,"by":{"0":"24"}},{"t":"case","label":"McNary v. Haitian Refugee Ctr.","cite":"498 U.S. 479","y":1991,"id":"1990/89-1332","sc":1,"by":{"0":"42","1":"38, 41","2":"20"}},{"t":"case","label":"Nasrallah v. Barr","cite":"590 U.S. 573","y":2020,"id":"2019/18-1432","sc":1,"by":{"0":"39"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Def.","cite":"583 U.S. 109","y":2018,"url":"https://supreme.justia.com/cases/federal/us/583/109/","sc":1,"by":{"0":"18"}},{"t":"case","label":"Nat’l Rifle Ass’n v. Vullo","cite":"602 U.S. 175","y":2024,"id":"2023/22-842","sc":1,"by":{"0":"9"}},{"t":"case","label":"Oestereich v. Selective Serv. Sys. Local Bd. No. 11","cite":"393 U.S. 233","y":1968,"id":"1968/46","sc":1,"by":{"0":"24"}},{"t":"case","label":"Oklahoma v. Castro-Huerta","cite":"597 U.S. 629","y":2022,"id":"2021/21-429","sc":1,"by":{"0":"40","2":"20"},"q":[{"src":"brief","b":0,"text":"replace the actual text with speculation as to Congress’ intent.","cite":"597 U.S. 629, 642"}]},{"t":"case","label":"Parker Drilling Mgmt. Servs., Ltd. v. Newton","cite":"587 U.S. 601","y":2019,"id":"2018/18-389","sc":1,"by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"It is a commonplace of statutory interpretation that ‘Congress legislates against the backdrop of existing law.’","cite":"587 U.S. 601, 611"}]},{"t":"case","label":"Pereida v. Collins","cite":"2025 WL 1099947","y":2025,"court":"Fed. Cir. Apr. 14","by":{"0":"25"},"q":[{"src":"brief","b":0,"text":"lack[s] authority under 38 U.S.C. § 7261 to rule on","cite":"2025 WL 1099947"},{"src":"argument","who":"Justice Gorsuch","text":"And a year ago, in Pereida, the government took the position that even the Veterans Court couldn't consider constitutional questions, right?"},{"src":"argument","who":"Justice Gorsuch","text":"It wasn't a problem up until last year when you took the opposite position in Pereida, right?"}]},{"t":"case","label":"Pereira v. Sessions","cite":"585 U.S. 198","y":2018,"id":"2017/17-459","sc":1,"by":{"0":"17","2":"4"}},{"t":"case","label":"Prewitt v. McDonough","cite":"633 F. Supp. 3d 195","y":2022,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/633/195/","by":{"0":"15, 31-33, 36","2":"5"},"q":[{"src":"brief","b":0,"text":"did not ultimately rest on principles of constitutional avoidance.","cite":"633 F. Supp. 3d at 203"},{"src":"brief","b":0,"text":"call into question [Robison’s] continued vitality.","cite":"633 F. Supp. 3d at 203"}]},{"t":"case","label":"Rotkiske v. Klemm","cite":"589 U.S. 8","y":2019,"id":"2019/18-328","sc":1,"by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"particularly inappropriate where, as here, Congress has shown that it knows how to adopt the omitted language","cite":"589 U.S. 8, 14"}]},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"0":"26"},"q":[{"src":"brief","b":0,"text":"Congress includes particular language in one section of a statute but omits it in another section of the same Act, it is generally presumed that Congress acts intentionally.","cite":"464 U.S. 16, 23"}]},{"t":"case","label":"SAS Inst. Inc. v. Iancu","cite":"584 U.S. 357","y":2018,"id":"2017/16-969","sc":1,"by":{"0":"23, 39"}},{"t":"case","label":"Seiflein v. Collins","cite":"2025 WL 2267022","y":2025,"court":"Fed. Cir. Aug. 8","by":{"0":"42"}},{"t":"case","label":"Shinseki v. Sanders","cite":"556 U.S. 396","y":2009,"id":"2008/07-1209","sc":1,"by":{"0":"29, 37"},"q":[{"src":"brief","b":0,"text":"complex determinations in a specialized area of the law.","cite":"556 U.S. 396, 412"}]},{"t":"case","label":"Thunder Basin Coal Co. v. Reich","cite":"510 U.S. 200","y":1994,"id":"1993/92-896","sc":1,"by":{"0":"37-39, 41, 44","1":"12, 14, 16, 39-41","2":"3, 20-21"},"q":[{"src":"brief","b":0,"text":"fairly discernible in the statutory scheme.","cite":"510 U.S. at 207"},{"src":"brief","b":1,"text":"is the claim ‘outside the agency’s expertise’?","cite":"510 U.S. at 212"},{"src":"argument","who":"Justice Gorsuch","text":"And then just to be clear about the Thunder Basin point, you acknowledged that when dealing with an express provision like we have here, this Court generally determines the scope of preclusion simply by interpreting the words Congress has chosen, right?"}]},{"t":"case","label":"Traynor v. Turnage","cite":"485 U.S. 535","y":1988,"id":"1987/86-622","sc":1,"by":{"0":"5-7, 33-34, 36","1":"6, 28","2":"6"},"q":[{"src":"argument","who":"Justice Kagan","text":"… position with respect to such contention if it is necessary to a decision in a case.\" So, I mean, I think what the House report at least thinks that they were doing in changing the first part of that sentence, which is different from the second part of the sentence, which was changed in response to Traynor, but the first part of the sentence was changed, according to the House report, specifically for that reason, to saying we're also talking about -- about things that are necessary to -- to -- to making the decision, which includes these constitutional preconditions as to whether you can appl …"},{"src":"argument","who":"Mr. Barber","text":"And I think a good example of this is the Traynor versus Turnage angle because Petitioner accepts that one of Congress's purposes in enacting the VJRA was to abrogate this Court's decision in Traynor."}]},{"t":"case","label":"United States v. Arthrex, Inc.","cite":"594 U.S. 1","y":2021,"id":"2020/19-1434","sc":1,"by":{"0":"9, 27","2":"11-12"},"q":[{"src":"brief","b":0,"text":"a principal officer, if not the President himself, makes the final decision on how to exercise executive power.","cite":"594 U.S. 1, 21"},{"src":"argument","who":"Mr. Barber","text":"So, as a general matter, we know from Arthrex, page 20 of that decision, that the veterans' general scheme complies with the Appointments Clause."},{"src":"argument","who":"Mr. Chen","text":"But even if, even if the government was correct that the Secretary could order the BVA to keep on ordering reconsiderations until the Secretary's outcome -- preferred outcome was reached, that is the exact kind of back-channel jury-rigging that this court in Arthrex held was insufficient for purposes of the Appointments Clause."}]},{"t":"case","label":"vii United States v. Salerno","cite":"481 U.S. 739","y":1987,"id":"1986/86-87","sc":1,"by":{"0":"16"},"q":[{"src":"argument","who":"Mr. Chen","text":"But that's confusing because this Court uses that terminology in a more well-known context, which is the Salerno context, which is, you know, invalid as to all applications versus as to just some."}]},{"t":"case","label":"Weinberger v. Salfi","cite":"422 U.S. 749","y":1975,"id":"1974/74-214","sc":1,"by":{"0":"23-24, 32","1":"30"},"q":[{"src":"brief","b":0,"text":"beyond [an agency’s] jurisdiction to determine.","cite":"422 U.S. 749, 765"},{"src":"brief","b":0,"text":"was simply not within [Section] 211(a)’s express language.","cite":"422 U.S. at 761"},{"src":"brief","b":1,"text":"if § 211(a) reached constitutional challenges to statutory limitations, [and] absolutely no judicial consideration of the issue [were] available.","cite":"422 U.S. 749, 762"},{"src":"argument","who":"Mr. Barber","text":"Another case I would point you to is Weinberger. It was decided the year after Robison. That case had an express preclusion clause referring to claims arising under Title II of the Social Security Act."},{"src":"argument","who":"Mr. Chen","text":"And then one thing I'd like to address is the -- my -- my friend directed you to the case Weinberger, which did have -- did consider language about \"claim arising under\" the statute."}]},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 362","y":2000,"id":"1999/98-8384","sc":1,"by":{"0":"40"},"q":[{"src":"brief","b":0,"text":"must ‘give effect, if possible, to every clause and word of a statute.’","cite":"529 U.S. 362, 404"}]},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"10, 17, 44","1":"5, 13, 26"}},{"t":"const","label":"Article I, Section 9, Clause 3","clauses":[["attainder-ex-post-facto","Bills of Attainder and Ex Post Facto Laws"]],"text":"No Bill of Attainder or ex post facto Law shall be passed.","by":{"0":"10, 17, 44"}},{"t":"usc","label":"5 U.S.C. § 7521","url":"https://www.law.cornell.edu/uscode/text/5/7521","by":{"0":"27"}},{"t":"usc","label":"5 U.S.C. § 7532","url":"https://www.law.cornell.edu/uscode/text/5/7532","by":{"0":"27"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(b)(9)","(g)"],"by":{"0":"22, 22"}},{"t":"usc","label":"28 U.S.C. § 530D","url":"https://www.law.cornell.edu/uscode/text/28/530D","subs":["(a)(1)(B)(ii)"],"stext":{"head":"§530D. Report on enforcement of laws","paras":[[0,"(a) Report.—"],[1,"(1) In general.—The Attorney General shall submit to the Congress a report of any instance in which the Attorney General or any officer of the Department of Justice—"],[2,"(A) establishes or implements a formal or informal policy to refrain—"],[3,"(i) from enforcing, applying, or administering any provision of any Federal statute, rule, regulation, program, policy, or other law whose enforcement, application, or administration is within the responsibility of the Attorney General or such officer on the grounds that such provision is unconstitutional; or"],[3,"(ii) within any judicial jurisdiction of or within the United States, from adhering to, enforcing, applying, or complying with, any standing rule of decision (binding upon courts of, or inferior to those of, that jurisdiction) established by a final decision of any court of, or superior to those of, that jurisdiction, respecting the interpretation, construction, or application of the Constitution, any statute, rule, regulation, program, policy, or other law whose enforcement, application, or administration is within the responsibility of the Attorney General or such officer;"],[2,"(B) determines—"],[3,"(i) to contest affirmatively, in any judicial, administrative, or other proceeding, the constitutionality of any provision of any Federal statute, rule, regulation, program, policy, or other law; or"],[3,"(ii) to refrain (on the grounds that the provision is unconstitutional) from defending or asserting, in any judicial, administrative, or other proceeding, the constitutionality of any provision of any Federal statute, rule, regulation, program, policy, or other law, or not to appeal or request review of any judicial, administrative, or other determination adversely affecting the constitutionality of any such provision; or"],[2,"(C) approves (other than in circumstances in which a report is submitted to the Joint Committee on Taxation, pursuant to section 6405 of the Internal Revenue Code of 1986) the settlement or compromise (other than in bankruptcy) of any claim, suit, or other action—"],[3,"(i) against the United States (including any agency or instrumentality thereof) for a sum that exceeds, or is likely to exceed, $2,000,000, excluding prejudgment interest; or"],[3,"(ii) by the United States (including any agency or instrumentality thereof) pursuant to an agreement, consent decree, or order (or pursuant to any modification of an agreement, consent decree, or order) that provides injunctive or other nonmonetary relief that exceeds, or is likely to exceed, 3 years in duration: Provided, That for purposes of this clause, the term \"injunctive or other nonmonetary relief\" shall not be understood to include the following, where the same are a matter of public record—"],[4,"(I) debarments, suspensions, or other exclusions from Government contracts or grants;"],[4,"(II) mere reporting requirements or agreements (including sanctions for failure to report);"],[4,"(III) requirements or agreements merely to comply with statutes or regulations;"],[4,"(IV) requirements or agreements to surrender professional licenses or to cease the practice of professions, occupations, or industries;"],[4,"(V) any criminal sentence or any requirements or agreements to perform community service, to serve probation, or to participate in supervised release from detention, confinement, or prison; or"],[4,"(VI) agreements to cooperate with the government in investigations or prosecutions (whether or not the agreement is a matter of public record)."],[1,"(2) Submission of report to the congress.—For the purposes of paragraph (1), a report shall be considered to be submitted to the Congress if the report is submitted to—"],[2,"(A) the majority leader and minority leader of the Senate;"],[2,"(B) the Speaker, majority leader, and minority leader of the House of Representatives;"],[2,"(C) the chairman and ranking minority member of the Committee on the Judiciary of the House of Representatives and the chairman and ranking minority member of the Committee on the Judiciary of the Senate; and"],[2,"(D) the Senate Legal Counsel and the General Counsel of the House of Representatives."],[0,"(b) Deadline.—A report shall be submitted—"],[1,"(1) under subsection (a)(1)(A), not later than 30 days after the establishment or implementation of each policy;"],[1,"(2) under subsection (a)(1)(B), within such time as will reasonably enable the House of Representatives and the Senate to take action, separately or jointly, to intervene in timely fashion in the proceeding, but in no event later than 30 days after the making of each determination; and"],[1,"(3) under subsection (a)(1)(C), not later than 30 days after the conclusion of each fiscal-year quarter, with respect to all approvals occurring in such quarter."],[0,"(c) Contents.—A report required by subsection (a) shall—"],[1,"(1) specify the date of the establishment or implementation of the policy described in subsection (a)(1)(A), of the making of the determination described in subsection (a)(1)(B), or of each approval described in subsection (a)(1)(C);"],[1,"(2) include a complete and detailed statement of the relevant issues and background (including a complete and detailed statement of the reasons for the policy or determination, and the identity of the officer responsible for establishing or implementing such policy, making such determination, or approving such settlement or compromise), except that—"],[2,"(A) such details may be omitted as may be absolutely necessary to prevent improper disclosure of national-security- or classified information, of any information subject to the deliberative-process-, executive-, attorney-work-product-, or attorney-client privileges, or of any information the disclosure of which is prohibited by section 6103 of the Internal Revenue Code of 1986, or other law or any court order if the fact of each such omission (and the precise ground or grounds therefor) is clearly noted in the statement: Provided, That this subparagraph shall not be construed to deny to the Congress (including any House, Committee, or agency thereof) any such omitted details (or related information) that it lawfully may seek, subsequent to the submission of the report; and"],[2,"(B) the requirements of this paragraph shall be deemed satisfied—"],[3,"(i) in the case of an approval described in subsection (a)(1)(C)(i), if an unredacted copy of the entire settlement agreement and consent decree or order (if any) is provided, along with a statement indicating the legal and factual basis or bases for the settlement or compromise (if not apparent on the face of documents provided); and"],[3,"(ii) in the case of an approval described in subsection (a)(1)(C)(ii), if an unredacted copy of the entire settlement agreement and consent decree or order (if any) is provided, along with a statement indicating the injunctive or other nonmonetary relief (if not apparent on the face of documents provided); and"],[1,"(3) in the case of a determination described in subsection (a)(1)(B) or an approval described in subsection (a)(1)(C), indicate the nature, tribunal, identifying information, and status of the proceeding, suit, or action."],[0,"(d) Declaration.—In the case of a determination described in subsection (a)(1)(B), the representative of the United States participating in the proceeding shall make a clear declaration in the proceeding that any position expressed as to the constitutionality of the provision involved is the position of the executive branch of the Federal Government (or, as applicable, of the President or of any executive agency or military department)."],[0,"(e) Applicability to the President and to Executive Agencies and Military Departments.—The reporting, declaration, and other provisions of this section relating to the Attorney General and other officers of the Department of Justice shall apply to the President (but only with respect to the promulgation of any unclassified Executive order or similar memorandum or order), to the head of each executive agency or military department (as defined, respectively, in sections 105 and 102 of title 5, United States Code) that establishes or implements a policy described in subsection (a)(1)(A) or is authorized to conduct litigation, and to the officers of such executive agency."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/530D?type=usc&year=mostrecent&link-type=html"},"by":{"0":"27","1":"34"}},{"t":"usc","label":"31 U.S.C. § 3336","url":"https://www.law.cornell.edu/uscode/text/31/3336","subs":["(c)"],"by":{"0":"22"}},{"t":"usc","label":"38 U.S.C. § 211","url":"https://www.law.cornell.edu/uscode/text/38/211","subs":["(a)","(a)(1970)"],"by":{"0":"5, 6, 7, 18, 32, 33, 34, 38","1":"5-7, 11, 13, 26-31"},"q":[{"src":"brief","b":0,"text":"decisions of the Administrator on any question of law or fact under any law administered by the [VA] providing benefits for veterans.","cite":"38 U.S.C. § 211(a)"},{"src":"brief","b":1,"text":"on any question of law or fact under any law administered by","cite":"38 U.S.C. 211(a)"},{"src":"argument","who":"Justice Kagan","text":"-- but it -- it -- it just like -- boy, it's just telling you why the first sentence of Section 211 was changed, and it has to do exactly with constitutional questions."}]},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"0":"17"}},{"t":"usc","label":"29 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/29/701","stext":{"head":"§701. Findings; purpose; policy","paras":[[0,"(a) Findings"],[0,"Congress finds that—"],[1,"(1) millions of Americans have one or more physical or mental disabilities and the number of Americans with such disabilities is increasing;"],[1,"(2) individuals with disabilities constitute one of the most disadvantaged groups in society;"],[1,"(3) disability is a natural part of the human experience and in no way diminishes the right of individuals to—"],[2,"(A) live independently;"],[2,"(B) enjoy self-determination;"],[2,"(C) make choices;"],[2,"(D) contribute to society;"],[2,"(E) pursue meaningful careers; and"],[2,"(F) enjoy full inclusion and integration in the economic, political, social, cultural, and educational mainstream of American society;"],[1,"(4) increased employment of individuals with disabilities can be achieved through implementation of statewide workforce development systems defined in section 3102 of this title that provide meaningful and effective participation for individuals with disabilities in workforce investment activities and activities carried out under the vocational rehabilitation program established under subchapter I, and through the provision of independent living services, support services, and meaningful opportunities for employment in integrated work settings through the provision of reasonable accommodations;"],[1,"(5) individuals with disabilities continually encounter various forms of discrimination in such critical areas as employment, housing, public accommodations, education, transportation, communication, recreation, institutionalization, health services, voting, and public services;"],[1,"(6) the goals of the Nation properly include the goal of providing individuals with disabilities with the tools necessary to—"],[2,"(A) make informed choices and decisions; and"],[2,"(B) achieve equality of opportunity, full inclusion and integration in society, employment, independent living, and economic and social self-sufficiency, for such individuals; and"],[1,"(7)(A) a high proportion of students with disabilities is leaving secondary education without being employed in competitive integrated employment, or being enrolled in postsecondary education; and"],[1,"(B) there is a substantial need to support such students as they transition from school to postsecondary life."],[0,"(b) Purpose"],[0,"The purposes of this chapter are—"],[1,"(1) to empower individuals with disabilities to maximize employment, economic self-sufficiency, independence, and inclusion and integration into society, through—"],[2,"(A) statewide workforce development systems defined in section 3102 of this title that include, as integral components, comprehensive and coordinated state-of-the-art programs of vocational rehabilitation;"],[2,"(B) independent living centers and services;"],[2,"(C) research;"],[2,"(D) training;"],[2,"(E) demonstration projects; and"],[2,"(F) the guarantee of equal opportunity;"],[1,"(2) to maximize opportunities for individuals with disabilities, including individuals with significant disabilities, for competitive integrated employment;"],[1,"(3) to ensure that the Federal Government plays a leadership role in promoting the employment of individuals with disabilities, especially individuals with significant disabilities, and in assisting States and providers of services in fulfilling the aspirations of such individuals with disabilities for meaningful and gainful employment and independent living;"],[1,"(4) to increase employment opportunities and employment outcomes for individuals with disabilities, including through encouraging meaningful input by employers and vocational rehabilitation service providers on successful and prospective employment and placement strategies; and"],[1,"(5) to ensure, to the greatest extent possible, that youth with disabilities and students with disabilities who are transitioning from receipt of special education services under the Individuals with Disabilities Education Act (20 U.S.C. 1400 et seq.) and receipt of services under section 794 of this title have opportunities for postsecondary success."],[0,"(c) Policy"],[0,"It is the policy of the United States that all programs, projects, and activities receiving assistance under this chapter shall be carried out in a manner consistent with the principles of—"],[1,"(1) respect for individual dignity, personal responsibility, self-determination, and pursuit of meaningful careers, based on informed choice, of individuals with disabilities;"],[1,"(2) respect for the privacy, rights, and equal access (including the use of accessible formats), of the individuals;"],[1,"(3) inclusion, integration, and full participation of the individuals;"],[1,"(4) support for the involvement of an individual's representative if an individual with a disability requests, desires, or needs such support; and"],[1,"(5) support for individual and systemic advocacy and community involvement."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/701?type=usc&year=mostrecent&link-type=html"},"by":{"0":"6","1":"6"}},{"t":"law","label":"Veterans’ Judicial Review Act, Pub. L. No. 100-687","url":"https://www.govinfo.gov/link/statute/102/4105","by":{"0":"4, 6-8, 11-16, 18-20, 23-30, 32-42","1":"2, 6, 7, 24","2":"2-3, 7-9, 12-15, 17, 19, 21"}},{"t":"reg","label":"38 C.F.R. § 4.73","url":"https://www.ecfr.gov/current/title-38/section-4.73","by":{"0":"19"}},{"t":"reg","label":"38 C.F.R. § 19.5","url":"https://www.ecfr.gov/current/title-38/section-19.5","by":{"0":"20"}},{"t":"reg","label":"38 C.F.R. § 20.101","url":"https://www.ecfr.gov/current/title-38/section-20.101","subs":["(a)"],"by":{"0":"20"}},{"t":"reg","label":"38 C.F.R. § 20.105","url":"https://www.ecfr.gov/current/title-38/section-20.105","by":{"0":"3, 20","1":"43","2":"8, 10, 12"},"q":[{"src":"brief","b":0,"text":"the Board is bound by applicable statutes.","cite":"38 C.F.R. § 20.105"}]},{"t":"reg","label":"54 Fed. Reg. 34,334","url":"https://www.govinfo.gov/link/fr/54/34334","by":{"0":"20"}},{"t":"case","label":"Abbott Labs. v. Gardner","cite":"387 U.S. 136","y":1967,"id":"1966/39","sc":1,"by":{"1":"6"}},{"t":"case","label":"Arellano v. McDonough","cite":"598 U.S. 1","y":2023,"id":"2022/21-432","sc":1,"by":{"1":"37"}},{"t":"case","label":"Board of Governors of the Fed. Reserve Sys. v. MCorp Fin., Inc.","cite":"502 U.S. 32","y":1991,"id":"1991/90-913","sc":1,"by":{"1":"38","2":"20"}},{"t":"case","label":"Boumediene v. Bush","cite":"553 U.S. 723","y":2008,"id":"2007/06-1195","sc":1,"by":{"1":"34"},"q":[{"src":"brief","b":1,"text":"independent obligation[] to interpret and uphold the Constitution.","cite":"553 U.S. 723, 798"}]},{"t":"case","label":"Cary v. Curtis","cite":"3 How. 236","y":1845,"url":"https://www.courtlistener.com/c/How./3/236/","by":{"1":"15"},"q":[{"src":"brief","b":1,"text":"invest[] them with jurisdiction either limited, concurrent, or exclusive, and * * * withhold[] jurisdiction from them in the exact degrees and character which to Congress may seem proper for the public good.","cite":"3 How. 236, 245"}]},{"t":"case","label":"Citizens United v. FEC","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"by":{"1":"25"}},{"t":"case","label":"Daylo v. Administrator of Veterans’ Affs.","cite":"501 F.2d 811","y":1974,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/501/811/","by":{"1":"5"}},{"t":"case","label":"Decatur v. Paulding","cite":"14 Pet. 497","y":1840,"url":"https://www.courtlistener.com/c/Pet./14/497/","by":{"1":"4"}},{"t":"case","label":"Estrada v. Shinseki","cite":"2013 WL 64489","y":2013,"court":"Vet. App. Jan. 7","by":{"1":"9"}},{"t":"case","label":"FCC v. Fox Television Stations, Inc.","cite":"556 U.S. 502","y":2009,"id":"2008/07-582","sc":1,"by":{"1":"21"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"[i]t is a ‘fundamental canon of statutory construction that the words of a statute must be read in their context and with a view to their place in the overall statutory scheme.’","cite":"529 U.S. 120, 133"}]},{"t":"case","label":"Fernandez v. United States","cite":"146 S. Ct. 1292","y":2026,"id":"2025/24-556","sc":1,"by":{"1":"16"}},{"t":"case","label":"George v. McDonough","cite":"596 U.S. 740","y":2022,"id":"2021/21-234","sc":1,"by":{"1":"4"},"q":[{"src":"brief","b":1,"text":"The law entitles veterans who have served on active duty in the United States military to receive benefits for disabilities caused or aggravated by their military service.","cite":"596 U.S. 740, 743"}]},{"t":"case","label":"Hall v. West","cite":"16 Vet. App. 391","y":1999,"court":"Feb. 9","url":"https://www.courtlistener.com/c/Vet.%20App./16/391/","by":{"1":"9, 39, 42"}},{"t":"case","label":"Jarkesy v. SEC","cite":"803 F.3d 9","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/803/9/","by":{"1":"25"}},{"t":"case","label":"Lockhart v. United States","cite":"577 U.S. 347","y":2016,"id":"2015/14-8358","sc":1,"by":{"1":"28"}},{"t":"case","label":"Lynch v. United States","cite":"292 U.S. 571","y":1934,"id":"scdb/1933-150","sc":1,"by":{"1":"5"}},{"t":"case","label":"M & K Emp. Solutions, LLC v. Trustees of the IAM Nat’l Pension Fund","cite":"146 S. Ct. 1224","y":2026,"id":"2025/23-1209","sc":1,"by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"generally do[es] not read limitations into statutes that do not appear in their text.","cite":"146 S. Ct. 1224, 1231"}]},{"t":"case","label":"Miller v. French","cite":"530 U.S. 327","y":2000,"id":"1999/99-224","sc":1,"by":{"1":"4"}},{"t":"case","label":"Montgomery v. Louisiana","cite":"577 U.S. 190","y":2016,"id":"2015/14-280","sc":1,"by":{"1":"36"},"q":[{"src":"brief","b":1,"text":"unconstitutional law is void, and is as no law,","cite":"577 U.S. 190, 204"}]},{"t":"case","label":"Mulder v. McDonald","cite":"805 F.3d 1342","y":2015,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/805/1342/","by":{"1":"9"}},{"t":"case","label":"National Fed’n of Indep. Bus. v. Department of Labor","cite":"595 U.S. 109","y":2022,"id":"2021/21a244","sc":1,"by":{"1":"25"}},{"t":"case","label":"Patterson v. McLean Credit Union","cite":"491 U.S. 164","y":1989,"id":"scdb/1988-115","sc":1,"by":{"1":"30"}},{"t":"case","label":"Philbrook v. McDonough","cite":"15 F.4th 1117","y":2021,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.4th/15/1117/","by":{"1":"42"}},{"t":"case","label":"Preseault v. ICC","cite":"853 F.2d 145","y":1988,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/853/145/","by":{"1":"22"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"by":{"1":"15"}},{"t":"case","label":"Rudisill v. McDonough","cite":"601 U.S. 294","y":2024,"id":"2023/22-888","sc":1,"by":{"1":"37, 38"}},{"t":"case","label":"Saunders v. Brown","cite":"4 Vet. App. 320","y":1993,"url":"https://www.courtlistener.com/c/Vet.%20App./4/320/","by":{"1":"33","2":"10"}},{"t":"case","label":"Shalala v. Illinois Council on Long Term Care, Inc.","cite":"529 U.S. 1","y":2000,"id":"1999/98-1109","sc":1,"by":{"1":"16"}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"by":{"1":"34"}},{"t":"case","label":"Van Buren v. United States","cite":"593 U.S. 374","y":2021,"id":"2020/19-783","sc":1,"by":{"1":"23"},"q":[{"src":"brief","b":1,"text":"extra icing on a cake already frosted.","cite":"593 U.S. 374, 394"}]},{"t":"case","label":"Veterans for Common Sense v. Shinseki","cite":"678 F.3d 1013","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/678/1013/","by":{"1":"27"},"q":[{"src":"argument","who":"Mr. Chen","text":"The Board of Veterans Appeals must make the VA's final decisions on all 511(a) matters, and no one in 1988 would have understood deciding the constitutionality of statutes as necessary to the BVA's decisions."},{"src":"argument","who":"Mr. Chen","text":"But Section 7104(a) specifically says that the final decisions on all matters that fall within Section 511(a) must be made by the Board of Veterans' Appeals."},{"src":"argument","who":"Mr. Chen","text":"We don't think that the Board of Veterans' Appeals can make that call. We think that -- well, most immediately, there is a regulation, 38 C.F.R. 20.105, that says that, in its decisions, the BVA is bound by statutes."}]},{"t":"case","label":"Wanless v. McDonough","cite":"2023 WL 8764419","y":2023,"court":"Vet. App. Dec. 19","by":{"1":"9"}},{"t":"case","label":"Wanless v. Shinseki","cite":"618 F.3d 1333","y":2010,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/618/1333/","by":{"1":"42"}},{"t":"case","label":"Webster v. Doe","cite":"486 U.S. 592","y":1988,"id":"1987/86-1294","sc":1,"by":{"1":"26"}},{"t":"case","label":"Whitney Nat’l Bank v. Bank of New Orleans & Tr. Co.","cite":"379 U.S. 411","y":1965,"id":"1964/26","sc":1,"by":{"1":"15"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"by":{"1":"23"}},{"t":"const","label":"Article III, Section 1","clauses":[["judicial-vesting","Judicial Vesting Clause"]],"text":"The judicial Power of the United States, shall be vested in one supreme Court, and in such inferior Courts as the Congress may from time to time ordain and establish. The Judges, both of the supreme and inferior Courts, shall hold their Offices during good Behaviour, and shall, at stated Times, receive for their Services, a Compensation, which shall not be diminished during their Continuance in Office.","by":{"1":"7, 15, 39"}},{"t":"const","label":"Article VI, Clause 3","clauses":[["religious-test","No Religious Test Clause"]],"text":"The Senators and Representatives before mentioned, and the Members of the several State Legislatures, and all executive and judicial Officers, both of the United States and of the several States, shall be bound by Oath or Affirmation, to support this Constitution; but no religious Test shall ever be required as a Qualification to any Office or public Trust under the United States.","by":{"1":"34"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"1":"5, 13, 26"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","by":{"1":"21"}},{"t":"usc","label":"5 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/5/1101","by":{"1":"23"}},{"t":"usc","label":"18 U.S.C. § 3582","url":"https://www.law.cornell.edu/uscode/text/18/3582","subs":["(c)(1)(A)"],"by":{"1":"16"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","by":{"1":"11, 15, 16"},"q":[{"src":"brief","b":1,"text":"original jurisdiction of all civil actions arising under the Constitution, laws, or treaties of the United States.","cite":"28 U.S.C. 1331"}]},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","by":{"1":"16"}},{"t":"usc","label":"38 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/38/301","subs":["(b)"],"by":{"1":"4"}},{"t":"usc","label":"38 U.S.C. § 505","url":"https://www.law.cornell.edu/uscode/text/38/505","by":{"1":"43"},"q":[{"src":"brief","b":1,"text":"require the opinion of the Attorney General on any question of law arising in the administration of the Department.","cite":"38 U.S.C. 505"}]},{"t":"usc","label":"38 U.S.C. § 511","url":"https://www.law.cornell.edu/uscode/text/38/511","subs":["(a)","(b)","(b)(1)","(b)(4)"],"stext":{"head":"§511. Decisions of the Secretary; finality","paras":[[0,"(a) The Secretary shall decide all questions of law and fact necessary to a decision by the Secretary under a law that affects the provision of benefits by the Secretary to veterans or the dependents or survivors of veterans. Subject to subsection (b), the decision of the Secretary as to any such question shall be final and conclusive and may not be reviewed by any other official or by any court, whether by an action in the nature of mandamus or otherwise."],[0,"(b) The second sentence of subsection (a) does not apply to—"],[1,"(1) matters subject to section 502 of this title;"],[1,"(2) matters covered by sections 1975 and 1984 of this title;"],[1,"(3) matters arising under chapter 37 of this title; and"],[1,"(4) matters covered by chapter 72 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/511?type=usc&year=mostrecent&link-type=html"},"by":{"1":"7, 7, 4, 4"},"q":[{"src":"brief","b":1,"text":"questions of law * * * necessary to a decision by the [VA] Secretary under a law that affects the provision of benefits by the Secretary to veterans.","cite":"38 U.S.C. 511(a)"},{"src":"brief","b":1,"text":"matters covered by chapter 72 of [Title 38].","cite":"38 U.S.C. 511(b)(4)"},{"src":"argument","who":"Mr. Chen","text":"We know from experience that what it does is it disclaims jurisdiction to decide that question, and then no one from the agency decides the question. And that's -- that violates even the government's reading of Section 511."}]},{"t":"usc","label":"38 U.S.C. § 1110","url":"https://www.law.cornell.edu/uscode/text/38/1110","by":{"1":"4"}},{"t":"usc","label":"38 U.S.C. § 1131","url":"https://www.law.cornell.edu/uscode/text/38/1131","by":{"1":"4, 9, 18, 19"},"q":[{"src":"argument","who":"Mr. Barber","text":"Under Section 511(a), Petitioner's challenge to the validity of Section 5313 is a question of law that is necessary to a decision under the benefits laws because the answer to that question dictates whether his benefits under Section 1131 must be reduced. 511(a) therefore channels his claim to the Veterans Court and the Federal Circuit."}]},{"t":"usc","label":"38 U.S.C. § 1310","url":"https://www.law.cornell.edu/uscode/text/38/1310","by":{"1":"4"}},{"t":"usc","label":"38 U.S.C. § 5307","url":"https://www.law.cornell.edu/uscode/text/38/5307","by":{"1":"9"}},{"t":"usc","label":"38 U.S.C. § 5313","url":"https://www.law.cornell.edu/uscode/text/38/5313","subs":["(a)(1)","(b)"],"stext":{"head":"§5313. Limitation on payment of compensation and dependency and indemnity compensation to persons incarcerated for conviction of a felony","paras":[[0,"(a)(1) To the extent provided in subsection (d) of this section, any person who is entitled to compensation or to dependency and indemnity compensation and who is incarcerated in a Federal, State, local, or other penal institution or correctional facility for a period in excess of sixty days for conviction of a felony shall not be paid such compensation or dependency and indemnity compensation, for the period beginning on the sixty-first day of such incarceration and ending on the day such incarceration ends, in an amount that exceeds—"],[1,"(A) in the case of a veteran with a service-connected disability rated at 20 percent or more, the rate of compensation payable under section 1114(a) of this title; or"],[1,"(B) in the case of a veteran with a service-connected disability not rated at 20 percent or more or in the case of a surviving spouse, parent, or child, one-half of the rate of compensation payable under section 1114(a) of this title."],[0,"(2) The provisions of paragraph (1) of this subsection shall not apply with respect to any period during which a person is participating in a work-release program or is residing in a halfway house."],[0,"(b)(1) All or any part of the compensation not paid to a veteran by reason of subsection (a) of this section may, as appropriate in an individual case, be apportioned under the same terms and conditions as are provided under section 5307 of this title."],[0,"(2) All or any part of the dependency and indemnity compensation not paid to a surviving spouse or child by reason of subsection (a) of this section may, as appropriate in an individual case, be apportioned as follows:"],[1,"(A) In the case of dependency and indemnity compensation not paid to a surviving spouse, any apportionment shall be to the surviving child or children."],[1,"(B) In the case of dependency and indemnity compensation not paid to a surviving child, any apportionment shall be to the surviving spouse or other surviving children, as applicable."],[0,"(3) No apportionment may be made under this subsection to or on behalf of any person who is incarcerated in a Federal, State, local, or other penal institution or correctional facility for conviction of a felony."],[0,"(c) The Secretary shall not assign to any veteran a rating of total disability based on the individual unemployability of the veteran resulting from a service-connected disability during any period during which the veteran is incarcerated in a Federal, State, local, or other penal institution or correctional facility for conviction of a felony."],[0,"(d) The provisions of subsection (a) of this section shall apply (1) with respect to any period of incarceration of a person for conviction of a felony committed after October 7, 1980, and (2) with respect to any period of incarceration on or after October 1, 1980, for conviction of a felony of a person who on October 1, 1980, is incarcerated for conviction of such felony and with respect to whom the action granting an award of compensation or dependency and indemnity compensation is taken on or after such date."],[0,"(e) For purposes of this section—"],[1,"(1) The term \"compensation\" includes disability compensation payable under section 1151 of this title."],[1,"(2) The term \"dependency and indemnity compensation\" means death compensation payable under section 1121 or 1141 of this title, death compensation and dependency and indemnity compensation payable under section 1151 of this title, and any benefit payable under chapter 13 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/5313?type=usc&year=mostrecent&link-type=html"},"by":{"1":"7, 37, 7, 37, 7, 37"},"q":[{"src":"argument","who":"Mr. Chen","text":"The VA did not need to resolve Section 5313's validity to reduce Mr. Johnson's benefits in accordance with Section 5313. Indeed, a decision to disregard Section 5313 as unconstitutional would obviously not be in accordance with Section 5313."},{"src":"argument","who":"Mr. Barber","text":"Under Section 511(a), Petitioner's challenge to the validity of Section 5313 is a question of law that is necessary to a decision under the benefits laws because the answer to that question dictates whether his benefits under Section 1131 must be reduced. 511(a) therefore channels his claim to the Veterans Court and the Federal Circuit."}]},{"t":"usc","label":"38 U.S.C. § 7101","url":"https://www.law.cornell.edu/uscode/text/38/7101","subs":["(a)"],"by":{"1":"7, 37"},"q":[{"src":"brief","b":1,"text":"is under the administrative control and supervision of a chairman directly responsible to the Secretary,","cite":"38 U.S.C. 7101(a)"}]},{"t":"usc","label":"38 U.S.C. § 7103","url":"https://www.law.cornell.edu/uscode/text/38/7103","by":{"1":"37"}},{"t":"usc","label":"38 U.S.C. § 7104","url":"https://www.law.cornell.edu/uscode/text/38/7104","subs":["(a)","(c)"],"by":{"1":"7, 8, 20, 21, 23, 7, 8, 20, 21, 23"},"q":[{"src":"brief","b":1,"text":"bound in its decisions by the regulations of the Department, instructions of the Secretary, and the precedent opinions of the chief legal officer of the Department.","cite":"38 U.S.C. 7104(c)"}]},{"t":"usc","label":"38 U.S.C. § 7251","url":"https://www.law.cornell.edu/uscode/text/38/7251","by":{"1":"8"},"q":[{"src":"brief","b":1,"text":"exclusive jurisdiction to review decisions of the Board of Veterans’ Appeals.","cite":"38 U.S.C. 7251, 7252"}]},{"t":"usc","label":"38 U.S.C. § 7252","url":"https://www.law.cornell.edu/uscode/text/38/7252","subs":["(a)"],"by":{"1":"39, 39"},"q":[{"src":"argument","who":"Mr. Chen","text":"It could not. Seven -- Section 7252 precludes the government."}]},{"t":"usc","label":"38 U.S.C. § 7261","url":"https://www.law.cornell.edu/uscode/text/38/7261","subs":["(a)(1)","(a)(3)","(a)(3)(A)","(a)(3)(B)"],"stext":{"head":"§7261. Scope of review","paras":[[0,"(a) In any action brought under this chapter, the Court of Appeals for Veterans Claims, to the extent necessary to its decision and when presented, shall—"],[1,"(1) decide all relevant questions of law, interpret constitutional, statutory, and regulatory provisions, and determine the meaning or applicability of the terms of an action of the Secretary;"],[1,"(2) compel action of the Secretary unlawfully withheld or unreasonably delayed;"],[1,"(3) hold unlawful and set aside decisions, findings (other than those described in clause (4) of this subsection), conclusions, rules, and regulations issued or adopted by the Secretary, the Board of Veterans' Appeals, or the Chairman of the Board found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or in violation of a statutory right; or"],[2,"(D) without observance of procedure required by law; and"],[1,"(4) in the case of a finding of material fact adverse to the claimant made in reaching a decision in a case before the Department with respect to benefits under laws administered by the Secretary, hold unlawful and set aside or reverse such finding if the finding is clearly erroneous."],[0,"(b) In making the determinations under subsection (a), the Court shall review the record of proceedings before the Secretary and the Board of Veterans' Appeals pursuant to section 7252(b) of this title and shall—"],[1,"(1) take due account of the Secretary's application of section 5107(b) of this title; and"],[1,"(2) take due account of the rule of prejudicial error."],[0,"(c) In no event shall findings of fact made by the Secretary or the Board of Veterans' Appeals be subject to trial de novo by the Court."],[0,"(d) When a final decision of the Board of Veterans' Appeals is adverse to a party and the sole stated basis for such decision is the failure of the party to comply with any applicable regulation prescribed by the Secretary, the Court shall review only questions raised as to compliance with and the validity of the regulation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7261?type=usc&year=mostrecent&link-type=html"},"by":{"1":"39, 43, 43, 43, 43"},"q":[{"src":"brief","b":1,"text":"decide all relevant questions of law, [and] interpret constitutional, statutory, and regulatory provisions.","cite":"38 U.S.C. 7261(a)(1)"},{"src":"brief","b":1,"text":"contrary to constitutional right, power, privilege, or immunity.","cite":"38 U.S.C. 7261(a)(3)"},{"src":"argument","who":"Mr. Chen","text":"In Section 7261, Congress directed the CAVC to set aside BVA decisions that are contrary to constitutional right, so not as explicit as 7292 but still mentions the Constitution at least."}]},{"t":"usc","label":"38 U.S.C. § 7292","url":"https://www.law.cornell.edu/uscode/text/38/7292","subs":["(a)","(c)","(d)(1)","(d)(2)"],"by":{"1":"43, 43, 43, 43, 43"},"q":[{"src":"brief","b":1,"text":"the validity * * * of any statute * * * that was relied on by the Court in making the decision.","cite":"38 U.S.C. 7292(a)"},{"src":"brief","b":1,"text":"exclusive jurisdiction to review and decide any challenge to the validity of any statute or regulation or any interpretation thereof brought under [Section 7292], and to interpret constitutional and statutory provisions, to the extent presented and necessary to a decision.","cite":"38 U.S.C. 7292(c)"}]},{"t":"reg","label":"38 C.F.R. § 20.906","url":"https://www.ecfr.gov/current/title-38/section-20.906","subs":["(c)"],"by":{"1":"43"}},{"t":"case","label":"Feliciano v. DOT","cite":"605 U.S. 38","y":2025,"url":"https://supreme.justia.com/cases/federal/us/605/38/","sc":1,"by":{"2":"10"}},{"t":"case","label":"FS Credit Opportunities Corp. v. Saba Cap. Master Fund, Ltd.","cite":"146 S. Ct. 1546","y":2026,"id":"2025/24-345","sc":1,"by":{"2":"18"},"q":[{"src":"brief","b":2,"text":"to see how [its] authors used the words on which this case turns.","cite":"146 S. Ct. 1546, 1557"}]},{"t":"case","label":"Jones Bros., Inc. v. Sec’y of Lab.","cite":"898 F.3d 669","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/898/669/","by":{"2":"16"}},{"t":"case","label":"Maricopa County v. Lopez-Valenzuela","cite":"574 U.S. 1006","y":2014,"url":"https://supreme.justia.com/cases/federal/us/574/1006/","sc":1,"by":{"2":"15"},"q":[{"src":"brief","b":2,"text":"a strong presumption in favor of granting writs of certiorari","cite":"574 U.S. 1006, 1007"}]},{"t":"case","label":"McLaughlin Chiropractic Assocs., Inc. v. McKesson Corp.","cite":"606 U.S. 146","y":2025,"id":"2024/23-1226","sc":1,"by":{"2":"21"}},{"t":"case","label":"Monsalvo v. Bondi","cite":"604 U.S. 712","y":2025,"url":"https://supreme.justia.com/cases/federal/us/604/712/","sc":1,"by":{"2":"7-8"}},{"t":"const","label":"Article II","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"],["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"],["take-care","Take Care Clause"],["impeachment","Impeachment"]],"by":{"2":"14"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"2":"14, 17, 20"}}]};